from collections import Counter

MOD = 10**9+7

def judge(N: int, A: list) -> int:
    # 報告数カウンタ
    cnt = Counter(A)

    # 奇数
    if N%2 == 1:
        #矛盾チェック
        for k,v in cnt.items():
            if k==0:
                if v != 1:
                    return 0
            else:
                if v != 2:
                    return 0

        # 矛盾がなければ2**(N//2)
        ans = 1
        for i in range(N//2):
            ans = (ans*2) %MOD

        return ans

    else:
        #矛盾チェック
        for k,v in cnt.items():
            if v != 2:
                return 0

        # 矛盾がなければ2**(N//2)
        ans = 1
        for i in range(N//2):
            ans = (ans*2) %MOD

        return ans

