def get_primes(lim):
    primes = []
    is_primes = [True for _ in range(lim)]
    for i in range(2, lim):
        if is_primes[i]:
            primes.append(i)
            for j in range(i * 2, lim, i):
                is_primes[j] = False

    return primes


def prime_factorization(n, primes):
    m = n
    factors = []
    for prime in primes:
        if m < prime:
            break

        while m % prime == 0:
            factors.append(prime)
            m /= prime

    if m > 1:
        factors.append(m)
    return factors


