def cnt_facts(n):
    a = 2
    lst = []
    while a**2 <= n:
        if n % a == 0:
            ex = 0
            while n % a == 0:
                ex += 1
                n //= a
            lst.append([a, ex])
        a += 1

    if n != 1: lst.append([n,1])

    return lst

