from math import sqrt

def make_prime_list(n):
    if n < 2:
        return []
    numbers = [i for i in range(n)]
    numbers[1] = 0
    for number in numbers:
        if number > sqrt(n):
            break
        if number == 0:
            continue
        for non in range(2*number, n, number):
            numbers[non] = 0
    return [number for number in numbers if number != 0]

