sys.setrecursionlimit(300000)


def solve(x: int):
    ret = (x // 11) * 2
    if (x % 11) <= 0:
        ret += 0
    elif (x % 11) <= 6:
        ret += 1
    else:
        ret += 2
    print(ret)
    return


def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    x = int(next(tokens))  # type: int
    solve(x)

if __name__ == '__main__':
    main()

