def rotate(s,deg):
    if deg==180:
        return s.translate(str.maketrans({'U': 'D', 'D': 'U', 'L':'R', 'R':'L'}))
    elif deg==90:
        return s.translate(str.maketrans({'U': 'L', 'D': 'R', 'L':'D', 'R':'U'}))
    elif deg==-90:
        return s.translate(str.maketrans({'U': 'R', 'D': 'L', 'L':'U', 'R':'D'}))
def mirror(s,direc):
    if direc=="x":
        return s.translate(str.maketrans({'L':'R', 'R':'L'})) 
    elif direc=="y":
        return s.translate(str.maketrans({'U': 'D', 'D': 'U'}))
