def mytranspose(A):
    return list(map(list,zip(*A)))

def myrotate(A):
    # 盤面や行列の左90度回転
    # 転置してから，上下逆にする
    # （もし右90度回転にしたい場合は，上下逆にしてから転置すれば良い．）
    B = mytranspose(A)
    C = B[::-1]
    return C

