import math

def solve(K: int, S: int):
    x_min = max(0, S-2*K)
    x_max = min(S, K)
    ans = 0
    for x in range(x_min, x_max+1):
        yz_sum = S-x
        if yz_sum < K:
            ans += (yz_sum + 1)
        else:
            ans += (K - (yz_sum - K) + 1)

    print(ans)
    return


