import numpy as np
import sys
from heapq import heappop, heappush

class Dijkstra:
    def __init__(self, n):
        self.ans = [-1] * n
        self.pre = [None] * n

    def dijkstra(self, G, start = 0):
        self.ans[start] = 0
        candidate = []
        for g in G[start]:
            heappush(candidate, g + (start, ))
        while candidate:
            m, i, p = heappop(candidate)
            if self.ans[i] >= 0:
                continue
            self.ans[i] = m
            self.pre[i] = p
            for (w, g) in G[i]:
                if self.ans[g] == -1:
                    heappush(candidate, (m + w, g, i))
                else:
                    pass

    def route(self, s, g):
        if self.pre[g] == None: return str(s)
        return self.route(s, self.pre[g]) + ' ' + str(g)


