def bfs(u, nList):
    n = len(nList)
    d = [0]*n
    visited = [False]*n
    queue = deque()
    visited[u] = True
    queue.append(u)
    while len(queue) > 0:
        u = queue.popleft()
        for v in nList[u]:
            if not visited[v]:
                d[v] = d[u] + 1
                visited[v] = True
                queue.append(v)
    return d

