"""
N: 頂点数，G: 頂点iから張られる有向辺のリスト．(v, cost)を持つ．，s: 開始点
多分O(N + Mlog(N))
"""
def dijkstra(N, G, s):
    que = [(0, s)]  # (v時点のcost, v)
    dist = [INF] * N
    dist[s] = 0
    while que:
        c_tot, v = heappop(que)
        if dist[v] != c_tot:     # すでに短い経路が見つかっている
            continue
        for nv, cost in G[v]:
            if c_tot + cost < dist[nv]:
                dist[nv] = c_tot + cost
                heappush(que, (dist[nv], nv))
    return dist


