def pushpush():
    n = read_as(int)
    a_ = read_as(int, ...)

    d: deque[int] = deque()
    to_left = d.appendleft; to_right = d.append

    for i, x in enumerate(a_):
        if i % 2:
            to_right(x)
        else:
            to_left(x)

    if not n % 2: d.reverse()
    return d

if __name__ == '__main__':
    iprint(pushpush())

