    n = II()
    a = input().split()
    a_even = []
    a_odd = []
    for i in range(n//2 * 2):
        if(i%2 == 0):
            a_even.append(a[i])
        else:
            a_odd.insert(0,a[i])
    if(n%2 == 0):
        Out = ' '.join(a_odd) + ' ' + ' '.join(a_even)
        print(Out)
    else:
        Out_list = a_odd + a_even + a[-1:]
        Out_list.reverse()
        print(' '.join(Out_list))
    return
