import collections


def solve_abc066c(n, A):
    b = collections.deque()

    is_reversed = False

    for a in A:
        if not is_reversed:
            b.append(a)
        else:
            b.appendleft(a)

        is_reversed = not is_reversed

    if is_reversed:
        b = reversed(b)

    return ' '.join(map(str, b))


def main():
    n = int(input())
    A = list(map(int, input().split()))

    print(solve_abc066c(n, A))


