	a = list(map(int, input().split()))
	d = deque()
	is_even = True if n % 2 == 0 else False
	for i in range(n):
		if is_even:
			if (i+1) % 2 == 0:
				d.appendleft(a[i])
			else:
				d.append(a[i])
		else:
			if (i+1) % 2 == 0:
				d.append(a[i])
			else:
				d.appendleft(a[i])

	print(" ".join(list(map(str, d))))
resolve()

