      add = -acmA[0]-1
      ans = abs(-acmA[0]-1)
      acmA[0] = -1      

  for i in range(1,N):
    acmA[i] += add
    tmp_add = 0
    if sign == 1:
      if i%2==0:
        if acmA[i] <=0:
          tmp_add = -acmA[i]+1
      else:
        if acmA[i] >=0:
