def kumiawase(n):
  for i in range(n+1):
    for j in range(i+1):
      x = j
      y = i-j
      z = n-i
      yield x,y,z

def fact(n):
  if n <= 1: return 1
  return n * fact(n - 1)

def cont_add(n):
  if n == 1: return 1
  return n + cont_add(n - 1)

