def solve():
    [N, T] = [int(x) for x in input().split()]
    ts = [int(x) for x in input().split()]

    import collections
    stack = collections.deque()

    for t in ts:
        if not stack:
            stack.append((t, t+T))
            continue

        last = stack.pop()
        if last[1] >= t:
            stack.append((last[0], t+T))
        else:
            stack.append(last)
            stack.append((t, t+T))

    ans = 0
    for t1, t2 in stack:
        ans += (t2 - t1)

    return ans


