import sys

def f(S):
    '''
    >>> f('(')
    '('
    >>> f(')(')
    ')('
    >>> f('()')
    ''
    >>> f('(())(')
    '('
    >>> f('())')
    ')'
     '''
    stack = []
    for s in S:
        if s == ')':
            if stack and stack[-1] == '(':
                stack.pop()
            else:
                stack.append(')')
        else:
            stack.append(s)
    return ''.join(stack)


def solve(N: int, S: str):
    s = f(S)
    return '(' * s.count(')') + S + ')' * s.count('(')


