def d_insertion(N, S):
    need_left, need_right = 0, 0  # Sの左右にほしい'(', ')'の個数
    for c in S:
        if c == '(':
            # '('と対応する')'を仮に右端に補充することにする。
            # あとで')'が出てきたなら補充量を減らせばいい。
            need_right += 1
        else:
            if need_right == 0:
                need_left += 1  # 今出た')'と対応する'('がない。左に補充する
            else:
                need_right -= 1
    return '(' * need_left + S + ')' * need_right

