def solve(S):
    N=len(S)
    X=[0 for i in range(N+1)]
    for i in range(N):
        s=S[i]
        if s=="(":
            X[i+1]=X[i]+1
        else:
            X[i+1]=X[i]-1
    m=min(X)
    if m<0:
        return solve("("*abs(m)+S)
    elif X[N]!=0:
        return solve(S+")"*X[N])
    else:
        return S
