class modint(int):
    m = 10 ** 9 + 7
    def __new__(cls, v):
        return int.__new__(cls, v % modint.m)

    def __add__(self, other: int) -> 'modint':
        return modint(int.__add__(self, other))

    def __sub__(self, other: int) -> 'modint':
        return modint(int.__sub__(self, other))

    def __mul__(self, other: int) -> 'modint':
        return modint(int.__mul__(self, other))

    def __truediv__(self, other: int) -> 'modint':
        if other == 0: raise ZeroDivisionError
        return modint(int.__mul__(self, pow(other, self.m-2)))

    @classmethod
    def by(cls, m: int):
        cls.m = m

