        x,y=y,x
    if y-x>1:
        return 0

    ans=1
    mod=10**9+7
    for i in range(1, x+1):
        ans*=i
        ans%=mod
    for i in range(1, y+1):
        ans*=i
        ans%=mod
    if x==y:
        ans*=2
        ans%=mod
    return ans

