def solve(n: int, S: "List[str]"):
    ret = ''
    counts = [[0] * n for _ in range(26)]
    for i, s in enumerate(S):
        for c in s:
            counts[ord(c) - ord('a')][i] += 1
    #print(counts)
    for i, cnt in enumerate(counts):
        ret += ''.join([chr(ord('a') + i) for _ in range(min(cnt))])
    print(ret)
    return


