    A = [1000000 for i in range(26)]
    for s in S:
        B = [0 for i in range(26)]
        for c in s:
            B[a2i(c)] += 1
        for i in range(26):
            A[i] = min(A[i], B[i])
    ans = []
    for i in range(26):
        ans.append(i2a(i) * A[i])
    return "".join(ans)


