def BellmanFord(E, N, source):
	#E: graphに相当。E[a]は頂点aを始点とする辺のリストで辺の終点bと重みwが(b, w)の形で格納
	#N: 頂点の数
	#source: 始点

	d = [INF]*N    #グラフの初期化
	d[source] = 0  #始点は0

	#辺の緩和
	for i in range(N):
		for j in range(N):
			if not E[j]:  #E[j] == [] の時
				continue
			for edge, weight in E[j]:
				if d[edge] > d[j] + weight:
					d[edge] = d[j] + weight
					if i == N-1:
						d[edge] = -INF  #負の閉路により、 -INF  

	q = deque([source])
	check = [0]*N
	while q:
		p = q.pop()
		for edge, weight in E[p]:
			if check[edge] == 0:
				check[edge] = 1
			if d[p] == -INF:
				d[edge] = -INF

	return d #始点(source) から各点に向かう最小経路

