    D, P = {s: 0}, {}
    for rnd in G: #n = len(G) ラウンド
        changed = False
        for u in G:
            for v in G[u]:
                if relax(G, u, v, D, P):
                    changed = True
        if not changed: #変化がなかった場合終了
            break
    else: #nラウンドで終了しなかった場合、負のサイクルがある
        dn = D[N]
        for u in G:
            for v in G[u]:
                relax(G, u, v, D, P)
        if dn == D[N]:
            return -D[N]
        else:
            return 'inf'
    return -D[N]


