        super().__init__(n,m)
    def _input(self):
        for _ in range(self.m):
            a,b,w = map(int, input().split())
            self.Graph[a-1].append([b-1, -w])

    def output(self,v):
        return self.Graph[v]

INF = float('inf')
def belfor(graph,n,start,dist):
    dist[start] = 0
    for i in range(n):
        update = False
        for v in range(n):
            # dist[v] == INFなら緩和しない
            if dist[v] == INF: continue
            for e in graph.output(v):
                if i == n-1:
                    if dist[e[0]]  > dist[v] +e[1]:
                        dist[e[0]] = -INF
                else:
                    if dist[e[0]]  > dist[v] +e[1]:
                        dist[e[0]] = dist[v] +e[1]
    return dist


