def bellman_ford(v:int,e:list,s:int):
    l = [-float('inf')]*v # 各頂点への最大コスト
    l[s] = 0 # 自身への距離は0

    for i in range(v):
        update = False
        v_update = False
        for x,y,cost in e:
            if l[y] < l[x]+cost:
                update = True
                if y == v-1:
                    v_update = True
                l[y] = l[x]+cost
            else:
                continue
        if not update:
            break
        # 正の閉路がある場合は、更新がv回目に突入する。
        # 負の閉路がある場合は、更新がされない。
        if i == v-1 and v_update:
            return 'inf'
    # 一番最後のnodeのコストを返す。
    return l[-1]

