    N,M = MI()
    Edges = list()
    for _ in range(M):
        # a → bへコストcで移動する
        a,b,c = MI()
        a -= 1
        b -= 1
        # 辺は有向グラフ
        # 無向の場合は、逆向きの[b,a,c]も加える
        Edges.append([a,b,c])
    print(bellman_ford(N,Edges,0))

