        update = False
        for i, j, c in es:
            if d[i] != INF and d[j] > d[i]+c:
                d[j] = d[i] + c
                update = True
                update_count_cyc[j] = 1
        update_counter += update_count_cyc
        if not update:
            break
    else:
        flag = True
