def sec14_2(N, G):
    INF = pow(2, 60)
    distance = [INF] * N
    distance[0] = 0
    cycle = False

    for i in range(2 * N + 1):
        update = False

        for v in range(N):
            if distance == INF:
                continue

            for c in G[v]:
                if distance[c[0]] > distance[v] + c[1]:
                    distance[c[0]] = distance[v] + c[1]
                    update = True

                    if c[0] == N - 1 and i == 2 * N:
                        cycle = True

        if not update:
            break

    return -distance[N - 1], cycle


