import math

class BellmanFord:
    def __init__(self, graph):
        self.n = len(graph)
        self.graph = graph

    def solve(self, start):
        dp = [math.inf for _ in range(self.n)]
        dp[start] = 0 
        for _ in range(self.n):
            updated = False
            for i, edges in enumerate(self.graph):
                for j, cost_i2j in edges:
                    cost_s2j = dp[i] + cost_i2j
                    if cost_s2j < dp[j]:
                        dp[j] = cost_s2j
                        updated = True
            if not updated:
                break
        return dp

    def re_solve(self, dp):
        for _ in range(self.n):
            updated = False
            for i, edges in enumerate(self.graph):
                for j, cost_i2j in edges:
                    cost_s2j = dp[i] + cost_i2j
                    if cost_s2j < dp[j]:
                        dp[j] = cost_s2j
                        updated = True
            if not updated:
                break
        return dp

