def read():
    N = int(input().strip())
    S = []
    for i in range(N):
        s = int(input().strip())
        S.append(s)
    return N, S

def solve(N, S, SMAX=10000):
    dp = [[False for j in range(SMAX+1)] for i in range(N+1)]
    for i in range(N):
        dp[i][0] = True
    for i in range(N):
        for j in range(SMAX):
            if j-S[i] >= 0:
                dp[i+1][j] = dp[i][j] | dp[i][j-S[i]]
            else:
                dp[i+1][j] = dp[i][j]
    for j in range(SMAX, -1, -1):
        if j % 10 == 0:
            continue
        if dp[N][j]:
            return j
    return 0

