    l, r, d, u = 0, width, 0, height
    for query in queries:
        x, y, a = query
        if a == 1:
            l=max(l, x)
        elif a == 2:
            r=min(r, x)
        elif a == 3:
            d=max(d, y)
        elif a == 4:
            u=min(u, y)
    width = r-l
    height = u-d
    if width < 0 or height < 0:
        print(0)
    else:
        print(width * height)

