import sys


def solve(W: int, H: int, N: int, x: "List[int]", y: "List[int]", a: "List[int]"):
    table = [[True] * W for _ in range(H)]
    for xx, yy, aa in zip(x, y, a):
        for yyy in range(1, H+1):
            for xxx in range(1, W+1):
                if aa == 1 and xxx <= xx:
                    table[yyy-1][xxx-1] = False
                if aa == 2 and xxx > xx:
                    table[yyy-1][xxx-1] = False
                if aa == 3 and yyy <= yy:
                    table[yyy-1][xxx-1] = False
                if aa == 4 and yyy > yy:
                    table[yyy-1][xxx-1] = False
        #print(*["".join("o" if tt else "x" for tt in t) for t in table], sep="\n")
        #print("-"*10)
    return sum(sum(t) for t in table)


