def solve():
    W, H, N = map(int, input().split())
    D = [tuple(map(int, input().split())) for _ in range(N)]

    ans = 0
    for i in range(H):
        for j in range(W):
            for t in D:
                x, y, a = t
                if a == 1 and j < x:
                    break
                elif a == 2 and j >= x:
                    break
                elif a == 3 and i < y:
                    break
                elif a == 4 and i >= y:
                    break
            else:
                ans += 1

    print(ans)


