def solveProblem(XLine,YLine,PointCounter):
	graphPaper = [[1 for _ in range(0,YLine,+1)] for _ in range(0,XLine,+1)]
	xplot = list()
	yplot = list()
	processSelect = list()
	for _ in range(0,PointCounter,+1):
		xplotEach,yplotEach,processSelectEach = map(int,input().strip().split(' '))
		xplot.append(xplotEach)
		yplot.append(yplotEach)
		processSelect.append(processSelectEach)

	for i in range(0,PointCounter,+1):
		if processSelect[i]==1:
			xrange = range(0,xplot[i],+1)
			yrange = range(0,YLine,+1)
		elif processSelect[i]==2:
			xrange = range(xplot[i],XLine,+1)
			yrange = range(0,YLine,+1)
		elif processSelect[i]==3:
			xrange = range(0,XLine,+1)
			yrange = range(0,yplot[i],+1)
		elif processSelect[i]==4:
			xrange = range(0,XLine,+1)
			yrange = range(yplot[i],YLine,+1)
		for x in xrange:
			for y in yrange:
				graphPaper[x][y]=0
	menseki=0
	for x in range(0,XLine,+1):
		for y in range(0,YLine,+1):
			if graphPaper[x][y]==1:
				menseki = menseki + 1
	answer = menseki
	return answer


