def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.perf_counter()
        ret = f(*args, **kwargs)
        e = time.perf_counter()

        ep(e - s, 'sec')
        return ret

    return wrap

def Prim(g):
    V = list(g.keys())
    for v in g.values():
        V.extend(list(v.keys()))
    V = list(set(V))

    used = set([])
    q = []
    heapq.heappush(q, (0, V[0]))

    ret = 0
    while q:
        c, v = heapq.heappop(q)

        if v in used:
            continue
        used.add(v)
        ret += c
        for u in g[v]:
            heapq.heappush(q, (g[v][u], u))
    return ret


@mt
def slv(N, XY):
    g = defaultdict(dict)
    XYI = [(x, y, i) for i, (x, y) in enumerate(XY)]
    XYI.sort(key=itemgetter(0))
    for k in range(2):
        XYI.sort(key=itemgetter(k))
        for i in range(N):
            if i > 0:
                d = min(abs(XYI[i][0] - XYI[i-1][0]), abs(XYI[i][1] - XYI[i-1][1]))
                g[XYI[i][2]][XYI[i-1][2]] = d
                g[XYI[i-1][2]][XYI[i][2]] = d
            if i + 1 < N:
                d = min(abs(XYI[i][0] - XYI[i+1][0]), abs(XYI[i][1] - XYI[i+1][1]))
                g[XYI[i][2]][XYI[i+1][2]] = d
                g[XYI[i+1][2]][XYI[i][2]] = d
    return Prim(g)


