class UnionFind(object):
    def __init__(self, N) -> None:
        self.N = N
        self.par = [i for i in range(N)]
        self.rank = [0 for _ in range(N)]

    def root(self, x: int) -> int:
        if self.par[x] == x:
            return x
        return self.root(self.par[x])

    def unite(self, x, y: int) -> None:
        rx = self.root(x)
        ry = self.root(y)
        if rx == ry:
            return

        if self.rank[rx] < self.rank[ry]:
            rx, ry = ry, rx

        self.par[ry] = rx
        if self.rank[rx] == self.rank[ry]:
            self.rank[rx] += 1

    def same(self, x, y: int) -> bool:
        return self.root(x) == self.root(y)

def Kruskal(edges, v) -> int:
    u = UnionFind(v)
    sorted_edges = sorted(edges, key=lambda x: x[2])
    s = 0

    for v_1, v_2, cost in sorted_edges:
        if not u.same(v_1, v_2):
            u.unite(v_1, v_2)
            s += cost

    return s

