                if (UF.same(e[0], e[1])) == False:
                    UF.unite(e[0], e[1])
                    res += e[2]

            return res

        def edge(self):
            UF = UnionFind(len(self.V)) #頂点数でUnion Find Treeを初期化
            res_E = []
            for i in range(len(self.E)):
                e = self.E[i]

                if (UF.same(e[0], e[1])) == False:
                    UF.unite(e[0], e[1])
                    res_E.append(e)

