import sys


class UnionFind:
    def __init__(self, n) -> None:
        self.parents = [-1] * n  # direct parent (equals root after calling root on it or its descendants)
        self.sizes = [1] * n  # represents size if it's root
        self.n_groups = n

    def root(self, i: int) -> int:
        if self.parents[i] == -1:
            return i
        else:
            ret = self.root(self.parents[i])
            self.parents[i] = ret
            return ret

    def is_united(self, i: int, j: int):
        return self.root(i) == self.root(j)

    def unite(self, i: int, j: int) -> bool:
        r_i = self.root(i)
        r_j = self.root(j)
        if r_i == r_j:
            return False
        if self.sizes[r_i] < self.sizes[r_j]:
            self.parents[r_i] = r_j
            self.sizes[r_j] += self.sizes[r_i]
        else:
            self.parents[r_j] = r_i
            self.sizes[r_i] += self.sizes[r_j]
        self.n_groups -= 1
        return True


def resolve() -> None:
    N = int(sys.stdin.readline().strip())
    X = []
    Y = []
    for i in range(N):
        x, y = (int(x) for x in sys.stdin.readline().strip().split())
        X.append([x, i])
        Y.append([y, i])
    X.sort()
    Y.sort()
    edges_dict = {}
    INF = 10 ** 9
    for Z in (X, Y):
        for i in range(N-1):
            z1, i1 = Z[i]
            z2, i2 = Z[i+1]
            if i1 > i2:
                i1, i2 = i2, i1
            edges_dict[(i1, i2)] = min(edges_dict.get((i1, i2), INF), z2 - z1)

    edges = []
    for (i1, i2), dist in edges_dict.items():
        edges.append((dist, i1, i2))
    edges.sort()

    uf = UnionFind(N)
    ans = 0
    for dist, i1, i2 in edges:
        if uf.is_united(i1, i2):
            continue
        uf.unite(i1, i2)
        ans += dist

    print(ans)


