class UnionFind:
    def __init__(self, n):
        # ノード番号が1からの時に、indexとノード番号を合わせたい時は、n = n+1とする。
        self.par = [i for i in range(n)]
        self.rank = [0] * (n)

    # 検索
    def find(self, x):
        if self.par[x] == x:
            return x
        else:
            self.par[x] = self.find(self.par[x])
            return self.par[x]

    # 同じ集合に属するか判定
    def same_check(self, x, y):
        return self.find(x) == self.find(y)

    # 併合
    def union(self, x, y):
        "既に併合したものを併合するケースを想定して、同じ根の物同士の時は何もしない"
        if self.same_check(x,y):
            return
        x = self.find(x)
        y = self.find(y)
        if self.rank[x] < self.rank[y]:
            self.par[x] = y
        else:
            self.par[y] = x
            if self.rank[x] == self.rank[y]:
                self.rank[x] += 1

# 頂点の数(n)、辺とそのコストを表す配列([(cost,v1,v2),...])を引数にする
def kruskal(n:int,l:list):
    ans = 0
    cnt = 0
    u = UnionFind(n)
    heapq.heapify(l)
    while cnt < n-1:
        # print(l,cnt)
        cost,v1,v2 = heapq.heappop(l)
        if u.same_check(v1,v2):
            continue
        u.union(v1,v2)
        ans += cost
        cnt += 1
    return ans

