    uf = UnionFind(V)
    minimum_spanning_tree = []
    for edge in edges:
        start, end, weight = edge
        if not uf.same(start, end):
            uf.union(start, end)
            minimum_spanning_tree.append(edge)
    return minimum_spanning_tree


