def kruskal(N, graph):
    uf = UnionFind(N)
    edges = []
    sm_cost = 0
    graph.sort(reverse=True)
    while len(edges) < N-1:
        now = graph.pop()
        if not uf.same(now[1], now[2]):
            uf.union(now[1], now[2])
            edges.append(now)
            sm_cost += now[0]
    return edges, sm_cost

