def gen_neighbors(X, coords):
    N = len(X)
    for i in range(N-1):
        xs, i1 = X[i]
        xt, i2 = X[i+1]
        if i1 > i2:
            i1, i2 = i2, i1
        if (i1, i2) in coords:
            coords[i1, i2] = min(coords[i1, i2], abs(xt-xs))
        else:
            coords[i1, i2] = abs(xt-xs)
    return coords

