import sys

YES = "Yes"  # type: str
NO = "No"  # type: str


def solve(a: int, b: int, c: int):
    if (a + b + c) % 2 != 0:
        print(NO)
        return

    abc_ave = (a + b + c) // 2
    if a == abc_ave or b == abc_ave or c == abc_ave:
        print(YES)
    else:
        print(NO)
    return


