class game:
  def __init__(self, a, b, c):
    self.a = a;
    self.b = b;
    self.c = c;
    self.an = 0;
    self.bn = 0;
    self.cn = 0;
    self.am = len(a);
    self.bm = len(b);
    self.cm = len(c);

  def play(self, ch):
    if(ch == "a"):
      self.an += 1;
      if(self.an == self.am+1):
        return "A"
      else:
        return game.play(self, self.a[self.an-1])
    elif(ch=="b"):
      self.bn += 1;
      if(self.bn == self.bm+1):
        return "B"
      else:
        return game.play(self, self.b[self.bn-1])
    else:
      self.cn += 1;
      if(self.cn == self.cm+1):
        return "C"
      else:
        return game.play(self, self.c[self.cn-1])

