# ABC045B - 3人でカードゲームイージー / Card Game for Three (ABC Edit)
from collections import deque


def main():
    S = {s: deque(list(input().rstrip())) for s in ("a", "b", "c")}
    cur = S["a"].popleft()
    while True:  # search greedily
        if not S[cur]:
            print(cur.upper())
            break
        cur = S[cur].popleft()


if __name__ == "__main__":
    main()

