def slove():
    import sys
    import collections
    input = sys.stdin.readline
    a = collections.deque(list(str(input().rstrip('\n'))))
    b = collections.deque(list(str(input().rstrip('\n'))))
    c = collections.deque(list(str(input().rstrip('\n'))))
    q = "a"
    while True:
        if q == "a":
            if len(a) != 0:
                q = a.popleft()
            else:
                print("A")
                exit()
        elif q == "b":
            if len(b) != 0:
                q = b.popleft()
            else:
                print("B")
                exit()
        elif q == "c":
            if len(c) != 0:
                q = c.popleft()
            else:
                print("C")
                exit()



if __name__ == '__main__':
    slove()

